// Baked landmass for the Atlas (generated: do not edit by hand).
// Natural Earth 1:50m land (world-atlas land-50m), rasterized offline:
// - WORLD: 360×180 bit-grid, 1° cells, row 0 = 90°N, column 0 = 180°W
//   (feeds the globe's land dots);
// - TILES: one 75×50 pixel map per place for the postcards, centred on
//   (lat, lon) and `span` degrees of longitude wide, latitude scaled by
//   cos(lat) so shapes stay true. A place without a tile falls back to the
//   world grid at runtime (coarser, still correct).
// Bits are packed LSB-first, row-major, base64.

export const WORLD_W = 360;
export const WORLD_H = 180;
export const WORLD = "";

export const TILE_W = 75;
export const TILE_H = 50;

export type Tile = { lat: number; lon: number; span: number; bits: string };

